        .connectTimeout(Duration.ofSeconds(10))
        .build();

    public static PlayerData getPlayerData(String username) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(java.net.URI.create(BASE_URL + "/player/" + username))
            .header("User-Agent", "OSRS-RivalRadar/1.0")
            .timeout(Duration.ofSeconds(15))
            .GET()
            .build();
        HttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());
        return parsePlayerData(response.body());
    }

    public static PlayerData[] comparePlayers(String[] usernames) throws Exception {
        PlayerData[] players = new PlayerData[usernames.length];
        for (int i = 0; i < usernames.length; i++) {
            players[i] = getPlayerData(usernames[i]);
        }
        return players;
    }

